from django.db.models import F, Q


WINNING_SCORE = 11


def mark_finished_games(apps, schema_editor):
    """Games that already reached the winning score are finished."""
    Game = apps.get_model("game", "Game")
    finished = Game.objects.filter(
        Q(player1_score__gte=WINNING_SCORE) | Q(player2_score__gte=WINNING_SCORE)
    )
    finished.filter(player1_score__gt=F("player2_score")).update(
        status="finished", winner=F("player1")
    )
    finished.filter(player2_score__gt=F("player1_score")).update(
        status="finished", winner=F("player2")
    )


